                    // 删除关联图片
                    if (!string.IsNullOrEmpty(qimage))
                    {
                        try
                        {
                            string fp = Server.MapPath("~/" + qimage);
                            if (System.IO.File.Exists(fp)) System.IO.File.Delete(fp);
                        }
                        catch { }
                    }
                    // 删除选项图片
                    if (!string.IsNullOrEmpty(optAImg))
                    {
